"""Entity Consensus Construction evaluation.

Constructs consensus entity sets from N samples using frequency-based
thresholds with LP-weighted decisions for medium-confidence entities.
Evaluates against gold using span-based (start, end, type) F1.
"""

import json
import os
import sys
import statistics
from collections import Counter, defaultdict

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from evaluation import entity_strict_match

BASE = "/root/autodl-tmp/struct_self_consist_ie"

DATASETS = {
    "SciERC": {
        "path": f"{BASE}/output/exp_012_rerun_1024/samples.jsonl",
        "gold_filter": True,
    },
    "CoNLL": {
        "path": f"{BASE}/output/exp_002_conll_n16_r1024/samples.jsonl",
        "gold_filter": True,
    },
    "FewNERD": {
        "path": f"{BASE}/output/exp_027_fewnerd_n16/samples.jsonl",
        "gold_filter": True,
    },
}

THRESHOLDS = [
    {"high": 0.5, "medium": 0.1},
    {"high": 0.6, "medium": 0.2},
    {"high": 0.7, "medium": 0.3},
    {"high": 0.8, "medium": 0.4},
]


def load_data(path, gold_filter=True):
    instances = []
    with open(path) as f:
        for line in f:
            obj = json.loads(line)
            if gold_filter and len(obj["gold"]["entities"]) == 0:
                continue
            instances.append(obj)
    return instances


def span_set(entities):
    return set((e["start"], e["end"], e["type"]) for e in entities)


def entity_f1(pred_entities, gold_entities):
    pred = span_set(pred_entities)
    gold = span_set(gold_entities)
    if len(pred) == 0 and len(gold) == 0:
        return 1.0
    if len(pred) == 0 or len(gold) == 0:
        return 0.0
    tp = len(pred & gold)
    if tp == 0:
        return 0.0
    p = tp / len(pred)
    r = tp / len(gold)
    return 2 * p * r / (p + r)


def get_sample_mean_logprob(sample, inst, idx):
    if "mean_logprob" in sample:
        return sample["mean_logprob"]
    if "logprobs" in inst and idx < len(inst["logprobs"]):
        return inst["logprobs"][idx]
    return None
